 page.evaluate('''()=>{const shell=document.querySelector('.shell');shell.dataset.la22Route='catalog';document.querySelector('nav .sel').classList.remove('sel');document.querySelector('nav [data-id="Catálogo LMS"]').classList.add('sel');const inside=document.querySelector('#inside');inside.dataset.la22Page='catalog';inside.innerHTML=`<div class="tiles la22-catalog-grid" data-la22-view="grid"><article class="card learning-card" data-direct="c3"><img class="learning-cover" src="/waves.webp"><span class="tag">SCORM</span><span class="tag">Arquivado</span><h2>SCORM</h2><p>DNA · 90 min</p><p>Novas matrículas estão suspensas.</p><div class="actions"><button data-act="editCourse">Editar curso</button><button data-act="courseState">Reativar e publicar</button><button data-act="courseHistory">Histórico</button></div></article><article class="card learning-card" data-direct="c1"><img class="learning-cover" src="/waves.webp"><span class="tag">Vídeo</span><span class="tag">Publicado</span><h2>Informativos - Beta Clean</h2><p>Integração · 150 min</p><div class="actions"><button data-act="learn" data-id="e1" class="primary">Acessar</button></div></article></div>`}''')
 page.wait_for_selector('.learning-card[data-la23-card]');assert page.locator('.la23-cover-tag').count()==2;assert page.locator('[data-direct=c3]').get_by_text('Arquivado').is_visible();assert page.locator('[data-direct=c3] [data-act=selfAssign]').count()==0
 page.locator('.la23-manage summary').click();assert page.get_by_role('button',name='Editar curso').is_visible();page.get_by_role('button',name='Editar curso').click();assert page.evaluate('actions.at(-1)[0]')=='editCourse'
 page.locator('[data-direct=c1] [data-act=learn]').click();assert page.evaluate('actions.at(-1)')==['learn','e1']
 page.evaluate("document.querySelector('.la22-catalog-grid').dataset.la22View='list'");assert page.locator('.learning-card').first.evaluate("el=>getComputedStyle(el).display")=='grid'
 page.set_viewport_size({'width':390,'height':844});assert page.locator('.learning-card').first.evaluate("el=>getComputedStyle(el).display")=='flex'
 assert not errors,errors
 print('PASS: KPI scope, certificate count, ring, bell re-render, learning action, blocked course, archive, admin actions, grid/list and mobile.')
